// Tormenta20 1.6.5 ActorT20#applyDamageV2, copied verbatim from tormenta20.mjs (T20:7360-7451).
// Joined into a class body with new Function by the tests.
export const APPLY_DAMAGE_V2 = [
  "async applyDamageV2(roll, multiplier = 1, type = \"dano\") {",
  "\tconst { pv, pm } = this.system.attributes;",
  "\tconst rds = this.system.tracos?.resistencias;",
  "\tconst rdsEx = Object.entries(rds).reduce((acc, [key, value]) => {",
  "\t\tif (value.excecao) acc[key] = value.excecao;",
  "\t\treturn acc;",
  "\t}, {});",
  "\tconst final = {",
  "\t\tdamage: 0,",
  "\t\tloss: 0,",
  "\t\theal: 0,",
  "\t\ttempHP: 0,",
  "\t\tmana: 0,",
  "\t\tmanaGain: 0,",
  "\t\ttempMP: 0",
  "\t};",
  "",
  "\tconst damage = {};",
  "\tlet lastOperator = \"+\";",
  "\tfor (const { operator, total, options, faces, number } of roll.terms) {",
  "\t\tif (!operator) {",
  "\t\t\tconst flavor = options?.flavor ?? roll.terms[0]?.options.flavor ?? type;",
  "\t\t\tdamage[flavor] ??= {",
  "\t\t\t\tvalue: 0,",
  "\t\t\t\tporDado: 0,",
  "\t\t\t\trd: Number(rds[flavor]?.value) || 0",
  "\t\t\t};",
  "\t\t\tdamage[flavor].value += lastOperator == \"+\" ? total : total * -1;",
  "\t\t\tif (faces) damage[flavor].porDado += number;",
  "\t\t} else lastOperator = operator;",
  "\t}",
  "",
  "\tconst map = { curapv: \"heal\", curatpv: \"tempHP\", curapm: \"manaGain\", curatpm: \"tempMP\" };",
  "\tObject.entries(map).forEach(([key, value]) => {",
  "\t\tif (damage[key]) {",
  "\t\t\tfinal[value] += damage[key].value * -multiplier;",
  "\t\t\tdelete damage[key];",
  "\t\t}",
  "\t});",
  "\tif (damage.perda) {",
  "\t\tif (multiplier > 0) final.loss += damage.perda.value * multiplier;",
  "\t\telse final.heal += damage.perda.value;",
  "\t\tdelete damage.perda;",
  "\t}",
  "",
  "\tlet rdIgnorada = Math.abs(roll.options.rd ?? 0);",
  "\tfunction ignoraRD(damageType) {",
  "\t\tconst rd = Number(rds[damageType].value);",
  "\t\trds[damageType].value = Math.max(rd - rdIgnorada, 0);",
  "\t\trdIgnorada = Math.max(rdIgnorada - rd, 0);",
  "\t}",
  "",
  "\tif (rdIgnorada) ignoraRD(\"dano\");",
  "\tif (rds.dano?.value) final.damage -= rds.dano.value;",
  "\tfor (let [type, dmg] of Object.entries(damage)) {",
  "\t\tlet rd = 0;",
  "\t\t// Apply Damage Reduction for each type of damage",
  "\t\tif (type !== \"dano\") {",
  "\t\t\tif (rdIgnorada) ignoraRD(type);",
  "\t\t\trd = Number(rds[type]?.value ?? 0);",
  "\t\t}",
  "",
  "\t\tif (!foundry.utils.isEmpty(rdsEx) && !rdsEx[type]) {",
  "\t\t\trd += Number(Object.values(rdsEx)[0]);",
  "\t\t}",
  "",
  "\t\tif (multiplier > 0) {",
  "\t\t\tif (rds[type]?.imunidade) dmg.value = 0;",
  "\t\t\telse if (rds[type]?.vulnerabilidade) dmg.value = Math.floor(dmg.value * 1.5);",
  "\t\t\telse if (rds[type]?.danoPorDado) dmg.value += dmg.porDado;",
  "\t\t\tfinal.damage += Math.max(dmg.value * multiplier - rd, 0);",
  "\t\t} else final.heal += dmg.value;",
  "\t}",
  "\tfinal.damage = Math.max(final.damage, 0);",
  "\t// Deduct value from temp attr first",
  "\tconst hpt = Math.min(pv.temp, final.damage + final.loss);",
  "\tconst mpt = Math.min(pm.temp, final.mana);",
  "\t// Remaining goes to attr",
  "\tconst dhp = Math.clamp(pv.value + final.heal - (final.damage + final.loss - hpt), pv.min, pv.max);",
  "\tconst dmp = Math.clamp(pm.value + final.manaGain - (final.mana - mpt), pm.min, pm.max);",
  "",
  "\t// Update the Actor",
  "\tconst updates = {",
  "\t\t\"system.attributes.pv.temp\": pv.temp - hpt + final.tempHP,",
  "\t\t\"system.attributes.pv.value\": dhp,",
  "\t\t\"system.attributes.pm.temp\": pm.temp - mpt + final.tempMP,",
  "\t\t\"system.attributes.pm.value\": dmp",
  "\t};",
  "",
  "\tawait this.update(updates);",
  "\tawait this.displayDamageCard(damage, final, multiplier);",
  "}"
].join("\n");
